  FT["PH-H3375"] = {"id":"PH-H3375","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4173_1965.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"在伊洛伊洛省Batad市镇设立国立农业与职业中学，名称为Batad国立农业与职业中学，并授权为此拨款的法案","en":"An Act to Establish a National Agricultural and Vocational High School in the Municipality of Batad, Province of Iloilo, to be Known as Batad National Agricultural and Vocational High School, and to Authorize the Appropriation of Funds Therefor","orig":"An Act to Establish a National Agricultural and Vocational High School in the Municipality of Batad, Province of Iloilo, to be Known as Batad National Agricultural and Vocational High School, and to Authorize the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["education","environment"],"docNumber":"Republic Act No. 4173","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-02-26","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4173_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3375-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the direct supervision of the Director of Vocational Education, a national agricultural and vocational high school in the Municipality of Batad, Province of Iloilo, to be known as Batad National Agricultural and Vocational High School."}},{"id":"PH-H3375-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Upon the recommendation of the Director of Vocational Education, the President of the Philippines shall set aside and reserve such portion of the public land located within Iloilo as may be necessary and convenient for the establishment of the school and farm sites."}},{"id":"PH-H3375-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of two hundred fifty thousand pesos is hereby authorized to be appropriated out of funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of the said school for the fiscal year nineteen hundred sixty-five. Thereafter, the necessary sums for the said purpose shall be included in the annual General Appropriations Act."}},{"id":"PH-H3375-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: February 26, 1965."}}],"pack":"ph-p47","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Establish a National Agricultural and Vocational High School in the Municipality of Batad, Province of Iloilo, to be Known as Batad National Agricultural and Vocational High School, and to Authorize the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
